from typing import List

def reverseAndAppend(s: str) -> List[str]:
    seen, res = set(), []
    for i in range(1, len(s)):
        # 从下标 i 向左：反转 s[0..i]；从下标 i 向右：反转 s[i..]
        for cand in (s[:i + 1][::-1] + s[i + 1:], s[:i] + s[i:][::-1]):
            if cand != s and cand not in seen:
                seen.add(cand)
                res.append(cand)
    return res
